import Chart from 'https://esm.sh/chart.js@4.4.7/auto';
import { jsPDF } from 'https://esm.sh/jspdf@2.5.2';
import {supabase,db} from './erp-db.js';
import {SELLERS,QUOTE_STATUS,ORDER_STATUS,ORDER_STAGES,CRM_STAGES,TASK_PRIORITY,CATALOG_PRODUCTS,DEFAULT_AUTOMATIONS} from './erp-data.js';

const $=id=>document.getElementById(id);
const $$=sel=>[...document.querySelectorAll(sel)];
const brl=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
const pct=v=>`${Number(v||0).toFixed(1).replace('.',',')}%`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date());
const dateBR=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeZone:'UTC'}).format(new Date(`${String(v).slice(0,10)}T12:00:00Z`)):'—';
const dateTimeBR=v=>v?new Intl.DateTimeFormat('pt-BR',{dateStyle:'short',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date(v)):'—';
const ageDays=v=>Math.floor((Date.now()-new Date(v).getTime())/86400000);
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const code=(prefix)=>`${prefix}-${new Date().getFullYear()}-${Math.random().toString(36).slice(2,8).toUpperCase()}`;
const activeDate=v=>v&&String(v).slice(0,10)<localDate();
const minMargin=()=>Number(localStorage.getItem(`paco_min_margin_${state.user?.id}`)||50);
const paymentNames={pix:'Pix',dinheiro:'Dinheiro',debito:'Débito',credito:'Crédito',outro:'Outro'};

const state={user:null,settings:{},services:[],sales:[],movements:[],leads:[],investments:[],customers:[],products:[],quotes:[],quoteItems:[],orders:[],orderItems:[],productionSteps:[],tasks:[],suppliers:[],stock:[],stockMovements:[],purchaseRequests:[],receivables:[],payables:[],automations:[],charts:{},lastSale:null,section:'dashboard'};
let modalSubmit=null;

function toast(msg,error=false){const e=$('toast');e.textContent=msg;e.className=`toast show${error?' error':''}`;clearTimeout(window.__toast);window.__toast=setTimeout(()=>e.className='toast',3400)}
function showApp(on){$('loginView').classList.toggle('hidden',on);$('appView').classList.toggle('hidden',!on)}
function monthBounds(monthValue=null){const d=monthValue?new Date(`${monthValue}-01T12:00:00`):new Date();const y=d.getFullYear(),m=d.getMonth();const pad=n=>String(n).padStart(2,'0');return{start:`${y}-${pad(m+1)}-01T00:00:00-03:00`,end:`${y}-${pad(m+1)}-${pad(new Date(y,m+1,0).getDate())}T23:59:59-03:00`,y,m}}
function monthSales(){const b=monthBounds();return state.sales.filter(s=>s.created_at>=b.start&&s.created_at<=b.end)}
function monthMovements(monthValue=null){const b=monthBounds(monthValue);return state.movements.filter(s=>s.created_at>=b.start&&s.created_at<=b.end)}
function customerName(id){return state.customers.find(x=>x.id===id)?.name||'Cliente não informado'}
function productName(id){return state.products.find(x=>x.id===id)?.name||''}
function supplierName(id){return state.suppliers.find(x=>x.id===id)?.name||'—'}
function orderLabel(o){return o.code||`PED-${String(o.id).slice(0,6).toUpperCase()}`}
function quoteLabel(q){return q.code||`ORC-${String(q.id).slice(0,6).toUpperCase()}`}
function statusClass(status){if(['approved','ready','delivered','paid','done','active'].includes(status))return'green';if(['lost','cancelled','overdue','critical'].includes(status))return'red';if(['sent','printing','doing','print_queue'].includes(status))return'blue';if(['waiting','negotiation','waiting_approval','finishing','cutting','assembly','quality','partial'].includes(status))return'amber';return'dark'}
function empty(msg){return`<div class="empty">${esc(msg)}</div>`}
function stat(label,value,extra=''){return`<div class="stat-card"><span>${esc(label)}</span><strong>${value}</strong>${extra?`<small>${extra}</small>`:''}</div>`}
function optionList(rows,valueKey='id',labelKey='name',selected=''){return rows.map(x=>`<option value="${esc(x[valueKey])}" ${String(x[valueKey])===String(selected)?'selected':''}>${esc(x[labelKey])}</option>`).join('')}
function sellerOptions(selected=''){return`<option value="">Selecione</option>${SELLERS.map(x=>`<option ${x===selected?'selected':''}>${x}</option>`).join('')}`}

function nav(section){
  const target=$(`section-${section}`);if(!target)return;
  state.section=section;$$('.section').forEach(x=>x.classList.remove('active'));target.classList.add('active');$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.section===section));
  const titles={dashboard:'Visão geral',customers:'Clientes',quotes:'Orçamentos',orders:'Pedidos',production:'Produção',tasks:'Tarefas',sale:'Venda rápida',catalog:'Catálogo inteligente',funnel:'CRM / Funil',stock:'Estoque e compras',suppliers:'Fornecedores',finance:'Financeiro',investments:'Investimentos',ledger:'Lançamentos',automations:'Automações',settings:'Configurações'};
  $('pageTitle').textContent=titles[section]||section;$('sidebar').classList.remove('open');renderSection(section);
}

$$('.nav-item').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.section)));$$('[data-go]').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.go)));$('openSidebar').onclick=()=>$('sidebar').classList.add('open');$('closeSidebar').onclick=()=>$('sidebar').classList.remove('open');
$('newPrimaryBtn').onclick=()=>nav('sale');$('refreshBtn').onclick=async()=>{await refreshAll(true);toast('Dados atualizados.')};$('productionRefreshBtn').onclick=async()=>{await refreshAll(true);renderProduction()};
$('todayLabel').textContent=new Intl.DateTimeFormat('pt-BR',{dateStyle:'full',timeZone:'America/Sao_Paulo'}).format(new Date()).toUpperCase();$('ledgerMonth').value=localDate().slice(0,7);

$('loginForm').addEventListener('submit',async e=>{e.preventDefault();const{data,error}=await supabase.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(error)return toast('E-mail ou senha inválidos.',true);state.user=data.user;db.setUser(data.user);showApp(true);await refreshAll()});
$('logoutBtn').onclick=async()=>{await supabase.auth.signOut();state.user=null;showApp(false)};

async function restore(){const{data}=await supabase.auth.getSession();if(data.session){state.user=data.session.user;db.setUser(state.user);showApp(true);await refreshAll()}else showApp(false)}

async function loadOldCore(){
  const uid=state.user.id,b=monthBounds();
  const safe=async(fn,fallback=[])=>{try{const{data,error}=await fn();if(error)throw error;return data??fallback}catch(e){console.warn(e);return fallback}};
  const [settings,services,sales,movements,leads,investments]=await Promise.all([
    safe(()=>supabase.from('company_settings').select('*').eq('user_id',uid).maybeSingle(),{}),
    safe(()=>supabase.from('services').select('*').eq('user_id',uid).order('name'),[]),
    safe(()=>supabase.from('sales').select('*,sale_items(*)').eq('user_id',uid).gte('created_at',b.start).lte('created_at',b.end).order('created_at',{ascending:false}),[]),
    safe(()=>supabase.from('cash_movements').select('*').eq('user_id',uid).gte('created_at',b.start).lte('created_at',b.end).order('created_at',{ascending:false}),[]),
    safe(()=>supabase.from('leads').select('*').eq('user_id',uid).order('updated_at',{ascending:false}),[]),
    safe(()=>supabase.from('investments').select('*').eq('user_id',uid).order('created_at',{ascending:false}),[])
  ]);
  state.settings=settings||{trade_name:'Papel e Código',monthly_revenue_target:0,tax_rate:0};state.services=services||[];state.sales=sales||[];state.movements=movements||[];state.leads=leads||[];state.investments=investments||[];
}

async function loadERP(){
  const names=['customers','products','quotes','quote_items','orders','order_items','production_steps','tasks','suppliers','stock_items','stock_movements','purchase_requests','receivables','payables','automation_rules'];
  const data=await Promise.all(names.map(n=>db.list(n)));
  [state.customers,state.products,state.quotes,state.quoteItems,state.orders,state.orderItems,state.productionSteps,state.tasks,state.suppliers,state.stock,state.stockMovements,state.purchaseRequests,state.receivables,state.payables,state.automations]=data;
}

async function ensureSeeds(){
  if(!state.products.length){await db.insertMany('products',CATALOG_PRODUCTS);state.products=await db.list('products')}
  if(!state.automations.length){await db.insertMany('automation_rules',DEFAULT_AUTOMATIONS);state.automations=await db.list('automation_rules')}
}

async function refreshAll(silent=false){
  try{
    await db.detectERP();await Promise.all([loadOldCore(),loadERP()]);await ensureSeeds();await runAutonomy();await loadERP();renderAll();
    $('dbDot').classList.toggle('ok',db.cloudERP);$('dbStatus').textContent=db.cloudERP?'ERP em nuvem':'ERP local';$('schemaBanner').classList.toggle('hidden',db.cloudERP||sessionStorage.getItem('paco_hide_schema')==='1');
  }catch(e){console.error(e);if(!silent)toast('Alguns dados não puderam ser carregados.',true)}
}
$('dismissSchemaBanner').onclick=()=>{sessionStorage.setItem('paco_hide_schema','1');$('schemaBanner').classList.add('hidden')};

function renderAll(){renderDashboard();renderCustomers();renderQuotes();renderOrders();renderProduction();renderTasks();renderCatalog();renderFunnel();renderStock();renderSuppliers();renderFinance();renderInvestments();renderLedger();renderAutomations();fillSettings();refreshSaleProductOptions()}
function renderSection(section){const map={dashboard:renderDashboard,customers:renderCustomers,quotes:renderQuotes,orders:renderOrders,production:renderProduction,tasks:renderTasks,catalog:renderCatalog,funnel:renderFunnel,stock:renderStock,suppliers:renderSuppliers,finance:renderFinance,investments:renderInvestments,ledger:renderLedger,automations:renderAutomations,settings:fillSettings,sale:refreshSaleProductOptions};map[section]?.()}

function metrics(){
  const sales=monthSales(),revenue=sales.reduce((a,s)=>a+Number(s.total||0),0),direct=sales.reduce((a,s)=>a+(s.sale_items||[]).reduce((b,i)=>b+Number(i.unit_cost||0)*Number(i.quantity||0),0),0),mov=monthMovements(),opOut=mov.filter(x=>x.type==='saida'&&(x.nature||'operational')==='operational').reduce((a,x)=>a+Number(x.amount||0),0),tax=revenue*Number(state.settings.tax_rate||0)/100,operating=revenue-direct-opOut-tax,target=Number(state.settings.monthly_revenue_target||0);
  return{sales,revenue,direct,opOut,tax,operating,target,ticket:sales.length?revenue/sales.length:0};
}
function renderDashboard(){
  const m=metrics(),openQuotes=state.quotes.filter(q=>!['approved','lost','expired'].includes(q.status)),pipeline=state.leads.filter(l=>l.stage!=='entregue').reduce((a,l)=>a+Number(l.estimated_value||0),0)+openQuotes.reduce((a,q)=>a+Number(q.total||0),0),prod=state.orders.filter(o=>!['ready','delivered','cancelled'].includes(o.status)),lateOrders=prod.filter(o=>activeDate(o.promised_date)),openTasks=state.tasks.filter(t=>!['done','cancelled'].includes(t.status)),lateTasks=openTasks.filter(t=>t.due_at&&new Date(t.due_at)<new Date()),low=state.stock.filter(s=>Number(s.current_qty||0)-Number(s.reserved_qty||0)<=Number(s.minimum_qty||0));
  $('dashRevenue').textContent=brl(m.revenue);$('dashRevenueCount').textContent=`${m.sales.length} venda${m.sales.length===1?'':'s'}`;const targetPct=m.target?Math.min(999,m.revenue/m.target*100):0;$('dashTargetPct').textContent=m.target?`${pct(targetPct)} da meta`:'Meta não definida';$('dashTargetBar').style.width=`${Math.min(100,targetPct)}%`;$('dashProfit').textContent=brl(m.operating);$('dashProfit').classList.toggle('danger-text',m.operating<0);$('dashMargin').textContent=m.revenue?`${pct(m.operating/m.revenue*100)} margem operacional`:'Sem vendas';$('dashPipeline').textContent=brl(pipeline);$('dashOpenQuotes').textContent=`${openQuotes.length} orçamentos abertos`;$('dashProduction').textContent=prod.length;$('dashLateOrders').textContent=`${lateOrders.length} em risco`;$('dashTasks').textContent=openTasks.length;$('dashLateTasks').textContent=`${lateTasks.length} atrasadas`;$('dashLowStock').textContent=low.length;
  renderRevenueChart(m);renderSmartAlerts();renderDashboardMinis();
}
function renderRevenueChart(m){const {y,m:mo}=monthBounds(),days=new Date(y,mo+1,0).getDate(),daily=Array(days).fill(0);m.sales.forEach(s=>daily[new Date(s.created_at).getDate()-1]+=Number(s.total||0));let run=0;const cumulative=daily.map(v=>run+=v),elapsed=Math.max(1,new Date().getDate()),projected=m.revenue/elapsed*days;$('projectionPill').textContent=`Projeção ${brl(projected)}`;state.charts.revenue?.destroy();state.charts.revenue=new Chart($('revenueChart'),{type:'line',data:{labels:Array.from({length:days},(_,i)=>i+1),datasets:[{data:cumulative,borderWidth:2.5,tension:.3,pointRadius:0,fill:true,backgroundColor:'rgba(11,107,255,.07)',borderColor:'#0b6bff'}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{grid:{color:'#edf1f6'},ticks:{callback:v=>'R$ '+Number(v).toLocaleString('pt-BR')}}}}})}
function renderSmartAlerts(){const alerts=[];const lateTasks=state.tasks.filter(t=>!['done','cancelled'].includes(t.status)&&t.due_at&&new Date(t.due_at)<new Date());if(lateTasks.length)alerts.push(['danger',`${lateTasks.length} tarefa(s) atrasada(s)`,'Priorize antes que afetem os pedidos.','tasks']);const low=state.stock.filter(s=>Number(s.current_qty)-Number(s.reserved_qty)<=Number(s.minimum_qty));if(low.length)alerts.push(['warn',`${low.length} insumo(s) em nível crítico`,'Há risco de faltar material para novos pedidos.','stock']);const overdue=state.receivables.filter(r=>r.status!=='paid'&&r.due_date&&r.due_date<localDate());if(overdue.length)alerts.push(['danger',`${overdue.length} recebimento(s) vencido(s)`,brl(overdue.reduce((a,r)=>a+Number(r.amount)-Number(r.received_amount||0),0))+' em aberto.','finance']);const waiting=state.quotes.filter(q=>['sent','waiting'].includes(q.status)&&ageDays(q.updated_at||q.created_at)>=3);if(waiting.length)alerts.push(['warn',`${waiting.length} orçamento(s) sem resposta`,'Follow-up comercial recomendado.','quotes']);if(!alerts.length)alerts.push(['good','Operação sob controle','Nenhuma exceção crítica detectada agora.','dashboard']);$('smartAlerts').innerHTML=alerts.slice(0,5).map(a=>`<div class="alert-item ${a[0]}" data-open="${a[3]}"><div><b>${esc(a[1])}</b><span>${esc(a[2])}</span></div><button class="small-btn">Abrir</button></div>`).join('');$$('#smartAlerts [data-open]').forEach(x=>x.onclick=()=>nav(x.dataset.open))}
function renderDashboardMinis(){const counts=ORDER_STAGES.map(s=>[ORDER_STATUS[s],state.orders.filter(o=>o.status===s).length]).filter(x=>x[1]).slice(0,5);$('productionMini').innerHTML=counts.map(x=>`<div class="mini-item"><div><b>${x[0]}</b><span>etapa produtiva</span></div><strong>${x[1]}</strong></div>`).join('')||empty('Nenhum pedido em produção.');const open=state.leads.filter(l=>l.stage!=='entregue'),approved=state.leads.filter(l=>['aprovado','producao','pronto','entregue'].includes(l.stage));$('commercialMini').innerHTML=`<div class="mini-item"><div><b>Oportunidades abertas</b><span>${open.length} clientes</span></div><strong>${brl(open.reduce((a,l)=>a+Number(l.estimated_value||0),0))}</strong></div><div class="mini-item"><div><b>Conversão</b><span>aprovados / total</span></div><strong>${state.leads.length?pct(approved.length/state.leads.length*100):'0%'}</strong></div>`;const map={};monthSales().forEach(s=>(s.sale_items||[]).forEach(i=>{const k=i.description;map[k]??={r:0,c:0};map[k].r+=Number(i.total||0);map[k].c+=Number(i.unit_cost||0)*Number(i.quantity||0)}));$('rankingMini').innerHTML=Object.entries(map).map(([name,v])=>({name,p:v.r-v.c,m:v.r?(v.r-v.c)/v.r*100:0})).sort((a,b)=>b.p-a.p).slice(0,4).map(x=>`<div class="mini-item"><div><b>${esc(x.name)}</b><span>${pct(x.m)} margem</span></div><strong>${brl(x.p)}</strong></div>`).join('')||empty('Ainda sem dados de rentabilidade.')}

function renderCustomers(){const q=($('customerSearch').value||'').toLowerCase(),rows=state.customers.filter(c=>!q||[c.name,c.legal_name,c.phone,c.whatsapp,c.email].some(v=>String(v||'').toLowerCase().includes(q))).sort((a,b)=>a.name.localeCompare(b.name));const totalSales=monthSales().filter(s=>s.customer_name).length;$('customerStats').innerHTML=stat('Clientes cadastrados',state.customers.length)+stat('Ativos',state.customers.filter(x=>x.active!==false).length)+stat('Novos no mês',state.customers.filter(x=>String(x.created_at).slice(0,7)===localDate().slice(0,7)).length)+stat('Vendas identificadas',totalSales);$('customersList').innerHTML=rows.map(c=>{const os=state.orders.filter(o=>o.customer_id===c.id),qs=state.quotes.filter(o=>o.customer_id===c.id);return`<div class="record"><div class="record-main"><b>${esc(c.name)}</b><small>${esc(c.legal_name||c.segment||'Cliente')} · ${esc(c.whatsapp||c.phone||'sem telefone')}</small></div><div class="record-cell"><b>${qs.length} orçamento(s)</b><small>${os.length} pedido(s)</small></div><div class="record-cell"><b>${esc(c.seller_name||'—')}</b><small>${esc(c.source||'origem não informada')}</small></div><div class="record-actions"><button class="small-btn customer-wa" data-id="${c.id}">WhatsApp</button><button class="small-btn primary customer-edit" data-id="${c.id}">Editar</button></div></div>`}).join('')||empty('Nenhum cliente encontrado.');$$('.customer-edit').forEach(b=>b.onclick=()=>openCustomerModal(state.customers.find(x=>x.id===b.dataset.id)));$$('.customer-wa').forEach(b=>b.onclick=()=>{const c=state.customers.find(x=>x.id===b.dataset.id);openWhatsapp(c?.whatsapp||c?.phone)})}
$('customerSearch').oninput=renderCustomers;$('newCustomerBtn').onclick=()=>openCustomerModal();

function renderQuotes(){const filter=$('quoteStatusFilter').value,rows=state.quotes.filter(q=>!filter||q.status===filter).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),open=state.quotes.filter(q=>!['approved','lost','expired'].includes(q.status)),approved=state.quotes.filter(q=>q.status==='approved');$('quoteStats').innerHTML=stat('Orçamentos',state.quotes.length)+stat('Em aberto',open.length)+stat('Pipeline',brl(open.reduce((a,q)=>a+Number(q.total),0)))+stat('Conversão',state.quotes.length?pct(approved.length/state.quotes.length*100):'0%');$('quotesList').innerHTML=rows.map(q=>`<div class="record"><div class="record-main"><b>${esc(quoteLabel(q))} · ${esc(customerName(q.customer_id))}</b><small>${dateBR(q.created_at)} · V${q.version||1} · ${esc(q.seller_name||'sem responsável')}</small></div><div class="record-cell"><b>${brl(q.total)}</b><small>Custo ${brl(q.estimated_cost)} · ${pct(Number(q.estimated_margin||0)*100)}</small></div><div class="record-cell"><span class="status ${statusClass(q.status)}">${esc(QUOTE_STATUS[q.status]||q.status)}</span><small>Validade ${dateBR(q.valid_until)}</small></div><div class="record-actions"><button class="small-btn quote-pdf" data-id="${q.id}">PDF</button><button class="small-btn quote-edit" data-id="${q.id}">Editar</button>${q.status!=='approved'?`<button class="small-btn primary quote-approve" data-id="${q.id}">Aprovar</button>`:''}</div></div>`).join('')||empty('Nenhum orçamento.');$$('.quote-edit').forEach(b=>b.onclick=()=>openQuoteModal(state.quotes.find(x=>x.id===b.dataset.id)));$$('.quote-approve').forEach(b=>b.onclick=()=>approveQuote(b.dataset.id));$$('.quote-pdf').forEach(b=>b.onclick=()=>downloadQuote(state.quotes.find(x=>x.id===b.dataset.id)))}
$('quoteStatusFilter').onchange=renderQuotes;$('newQuoteBtn').onclick=()=>openQuoteModal();

function renderOrders(){const filter=$('orderStatusFilter').value,rows=state.orders.filter(o=>!filter||o.status===filter).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)),active=state.orders.filter(o=>!['ready','delivered','cancelled'].includes(o.status)),late=active.filter(o=>activeDate(o.promised_date));$('orderStats').innerHTML=stat('Pedidos',state.orders.length)+stat('Em produção',active.length)+stat('Prontos',state.orders.filter(o=>o.status==='ready').length)+stat('Em risco',late.length);$('ordersList').innerHTML=rows.map(o=>`<div class="record"><div class="record-main"><b>${esc(orderLabel(o))} · ${esc(customerName(o.customer_id))}</b><small>${esc(o.seller_name||'sem responsável')} · criado ${dateBR(o.created_at)}</small></div><div class="record-cell"><b>${brl(o.total)}</b><small>Custo estimado ${brl(o.estimated_cost)}</small></div><div class="record-cell"><span class="status ${statusClass(o.status)}">${esc(ORDER_STATUS[o.status]||o.status)}</span><small class="${activeDate(o.promised_date)?'danger-text':''}">Prazo ${dateBR(o.promised_date)}</small></div><div class="record-actions"><button class="small-btn order-edit" data-id="${o.id}">Editar</button>${!['ready','delivered','cancelled'].includes(o.status)?`<button class="small-btn primary order-next" data-id="${o.id}">Avançar</button>`:''}</div></div>`).join('')||empty('Nenhum pedido.');$$('.order-edit').forEach(b=>b.onclick=()=>openOrderModal(state.orders.find(x=>x.id===b.dataset.id)));$$('.order-next').forEach(b=>b.onclick=()=>advanceOrder(b.dataset.id))}
$('orderStatusFilter').onchange=renderOrders;$('newOrderBtn').onclick=()=>openOrderModal();

function renderProduction(){const stages=ORDER_STAGES.filter(s=>s!=='delivered'),orders=state.orders.filter(o=>o.status!=='delivered'&&o.status!=='cancelled');$('productionKanban').innerHTML=stages.map(stage=>{const rows=orders.filter(o=>o.status===stage);return`<div class="kanban-col" data-order-stage="${stage}"><div class="kanban-head"><strong>${esc(ORDER_STATUS[stage])}</strong><span>${rows.length}</span></div>${rows.map(o=>`<div class="kanban-card ${activeDate(o.promised_date)?'overdue critical':''}" draggable="true" data-order="${o.id}"><strong>${esc(orderLabel(o))}</strong><small>${esc(customerName(o.customer_id))}</small><div class="card-value">${brl(o.total)}</div><small>Prazo ${dateBR(o.promised_date)}</small><div class="card-foot"><span class="status ${o.priority>=80?'red':o.priority>=50?'amber':'dark'}">P${o.priority||0}</span><button class="small-btn order-next" data-id="${o.id}">Avançar</button></div></div>`).join('')}</div>`}).join('');$$('[data-order]').forEach(c=>c.addEventListener('dragstart',e=>e.dataTransfer.setData('text/order',c.dataset.order)));$$('[data-order-stage]').forEach(col=>{col.ondragover=e=>e.preventDefault();col.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/order');if(id)moveOrder(id,col.dataset.orderStage)}});$$('#productionKanban .order-next').forEach(b=>b.onclick=()=>advanceOrder(b.dataset.id))}

function renderTasks(){const filter=$('taskFilter').value||'open',today=localDate(),rows=state.tasks.filter(t=>{if(filter==='all')return true;if(filter==='done')return t.status==='done';if(filter==='late')return t.status!=='done'&&t.due_at&&new Date(t.due_at)<new Date();if(filter==='today')return String(t.due_at||'').slice(0,10)===today;return !['done','cancelled'].includes(t.status)}).sort((a,b)=>(a.due_at||'9999').localeCompare(b.due_at||'9999'));const open=state.tasks.filter(t=>!['done','cancelled'].includes(t.status)),late=open.filter(t=>t.due_at&&new Date(t.due_at)<new Date());$('taskStats').innerHTML=stat('Pendentes',open.length)+stat('Hoje',open.filter(t=>String(t.due_at||'').slice(0,10)===today).length)+stat('Atrasadas',late.length)+stat('Concluídas',state.tasks.filter(t=>t.status==='done').length);$('tasksList').innerHTML=rows.map(t=>`<div class="record"><div class="record-main"><b>${esc(t.title)}</b><small>${esc(t.description||customerName(t.customer_id)||'')} ${t.order_id?'· '+esc(orderLabel(state.orders.find(o=>o.id===t.order_id)||{})):''}</small></div><div class="record-cell"><span class="status ${statusClass(t.priority)}">${esc(TASK_PRIORITY[t.priority]||t.priority)}</span><small>${esc(t.assignee||'sem responsável')}</small></div><div class="record-cell"><b class="${t.status!=='done'&&t.due_at&&new Date(t.due_at)<new Date()?'danger-text':''}">${t.due_at?dateTimeBR(t.due_at):'Sem prazo'}</b><small>${t.estimated_minutes?`${t.estimated_minutes} min estimados`:''}</small></div><div class="record-actions"><button class="small-btn task-edit" data-id="${t.id}">Editar</button>${t.status!=='done'?`<button class="small-btn good task-done" data-id="${t.id}">Concluir</button>`:''}</div></div>`).join('')||empty('Nenhuma tarefa neste filtro.');$$('.task-edit').forEach(b=>b.onclick=()=>openTaskModal(state.tasks.find(x=>x.id===b.dataset.id)));$$('.task-done').forEach(b=>b.onclick=()=>completeTask(b.dataset.id))}
$('taskFilter').onchange=renderTasks;$('newTaskBtn').onclick=()=>openTaskModal();

function renderCatalog(){const query=($('catalogSearch').value||'').toLowerCase(),cat=$('catalogCategory').value,cats=[...new Set(state.products.map(p=>p.category))].sort();const current=cat;$('catalogCategory').innerHTML='<option value="">Todas as categorias</option>'+cats.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('');const rows=state.products.filter(p=>p.active!==false&&(!query||[p.name,p.category,p.subproduct].some(v=>String(v||'').toLowerCase().includes(query)))&&(!cat||p.category===cat)).sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name));$('catalogSummary').innerHTML=stat('Produtos ativos',state.products.filter(x=>x.active!==false).length)+stat('Categorias',cats.length)+stat('Com preço',state.products.filter(x=>Number(x.sale_price)>0).length)+stat('Margem mínima',pct(minMargin()));$('catalogGrid').innerHTML=rows.map(p=>{const margin=Number(p.sale_price)?(Number(p.sale_price)-Number(p.direct_cost))/Number(p.sale_price)*100:0;return`<article class="product-card"><span class="cat">${esc(p.category)}</span><h4>${esc(p.name)}</h4><p>${esc(p.subproduct||`${(p.custom_fields||[]).length} campo(s) personalizado(s) · ${(p.recipe||[]).length} item(ns) na receita`)}</p><div class="product-money"><div><strong>${brl(p.sale_price)}</strong><span> venda</span></div><div><span class="${margin&&margin<Number(p.minimum_margin||minMargin())?'danger-text':'good-text'}">${p.sale_price?pct(margin):'sem preço'}</span></div></div><div class="product-actions"><button class="small-btn product-edit" data-id="${p.id}">Configurar</button><button class="small-btn primary product-quote" data-id="${p.id}">Orçar</button></div></article>`}).join('')||empty('Nenhum produto encontrado.');$$('.product-edit').forEach(b=>b.onclick=()=>openProductModal(state.products.find(x=>x.id===b.dataset.id)));$$('.product-quote').forEach(b=>b.onclick=()=>openQuoteModal(null,b.dataset.id))}
$('catalogSearch').oninput=renderCatalog;$('catalogCategory').onchange=renderCatalog;$('newProductBtn').onclick=()=>openProductModal();$('seedCatalogBtn').onclick=async()=>{const existing=new Set(state.products.map(p=>p.name.toLowerCase()));const missing=CATALOG_PRODUCTS.filter(p=>!existing.has(p.name.toLowerCase()));if(!missing.length)return toast('O catálogo-base já está completo.');await db.insertMany('products',missing);state.products=await db.list('products');renderCatalog();toast(`${missing.length} produto(s) restaurado(s).`)};

function renderFunnel(){const open=state.leads.filter(l=>l.stage!=='entregue'),approved=state.leads.filter(l=>['aprovado','producao','pronto','entregue'].includes(l.stage));$('pipelineValue').textContent=brl(open.reduce((a,l)=>a+Number(l.estimated_value||0),0));$('conversionRate').textContent=state.leads.length?pct(approved.length/state.leads.length*100):'0%';$('crmKanban').innerHTML=CRM_STAGES.map(([key,label])=>{const rows=state.leads.filter(l=>l.stage===key);return`<div class="kanban-col" data-crm-stage="${key}"><div class="kanban-head"><strong>${esc(label)}</strong><span>${rows.length}</span></div>${rows.map(l=>`<div class="kanban-card" draggable="true" data-lead="${l.id}"><strong>${esc(l.customer_name)}</strong><small>${esc(l.service_interest||'Sem produto definido')}</small><div class="card-value">${brl(l.estimated_value)}</div><div class="card-foot"><small>${esc(l.seller_name||'—')}</small><button class="small-btn lead-edit" data-id="${l.id}">Editar</button></div></div>`).join('')}</div>`}).join('');$$('[data-lead]').forEach(c=>c.ondragstart=e=>e.dataTransfer.setData('text/lead',c.dataset.lead));$$('[data-crm-stage]').forEach(c=>{c.ondragover=e=>e.preventDefault();c.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/lead');if(id)moveLead(id,c.dataset.crmStage)}});$$('.lead-edit').forEach(b=>b.onclick=()=>openLeadModal(state.leads.find(x=>x.id===b.dataset.id)))}
