function renderStock(){const q=($('stockSearch').value||'').toLowerCase(),rows=state.stock.filter(s=>!q||[s.name,s.category,s.location].some(v=>String(v||'').toLowerCase().includes(q))).sort((a,b)=>a.name.localeCompare(b.name)),low=state.stock.filter(s=>Number(s.current_qty)-Number(s.reserved_qty)<=Number(s.minimum_qty)),value=state.stock.reduce((a,s)=>a+Number(s.current_qty)*Number(s.average_cost),0);$('stockStats').innerHTML=stat('Insumos',state.stock.length)+stat('Valor estimado',brl(value))+stat('Estoque crítico',low.length)+stat('Reservado',state.stock.filter(s=>Number(s.reserved_qty)>0).length);$('stockList').innerHTML=rows.map(s=>{const available=Number(s.current_qty)-Number(s.reserved_qty),critical=available<=Number(s.minimum_qty);return`<div class="record"><div class="record-main"><b>${esc(s.name)}</b><small>${esc(s.category||'Insumo')} · ${esc(s.location||'sem localização')}</small></div><div class="record-cell"><b class="${critical?'danger-text':''}">${available.toLocaleString('pt-BR')} ${esc(s.unit)}</b><small>${s.reserved_qty} reservado · mínimo ${s.minimum_qty}</small></div><div class="record-cell"><b>${brl(s.average_cost)}</b><small>${esc(supplierName(s.supplier_id))}</small></div><div class="record-actions"><button class="small-btn stock-move" data-id="${s.id}">Movimentar</button><button class="small-btn primary stock-edit" data-id="${s.id}">Editar</button></div></div>`}).join('')||empty('Nenhum insumo cadastrado.');$('purchaseSuggestions').innerHTML=low.map(s=>{const available=Number(s.current_qty)-Number(s.reserved_qty),suggested=Math.max(Number(s.minimum_qty)*2-available,Number(s.minimum_qty)-available);return`<div class="record"><div class="record-main"><b>${esc(s.name)}</b><small>Disponível ${available} ${esc(s.unit)} · mínimo ${s.minimum_qty}</small></div><div class="record-actions"><button class="small-btn primary purchase-create" data-id="${s.id}" data-q="${suggested}">Solicitar ${suggested}</button></div></div>`}).join('')||empty('Nenhuma reposição necessária.');$$('.stock-edit').forEach(b=>b.onclick=()=>openStockModal(state.stock.find(x=>x.id===b.dataset.id)));$$('.stock-move').forEach(b=>b.onclick=()=>openStockMovementModal(state.stock.find(x=>x.id===b.dataset.id)));$$('.purchase-create').forEach(b=>b.onclick=()=>createPurchaseSuggestion(b.dataset.id,Number(b.dataset.q)))}
$('stockSearch').oninput=renderStock;$('newStockBtn').onclick=()=>openStockModal();

