function renderFinance(){const recOpen=state.receivables.filter(r=>!['paid','cancelled'].includes(r.status)),payOpen=state.payables.filter(r=>!['paid','cancelled'].includes(r.status)),overdue=recOpen.filter(r=>r.due_date&&r.due_date<localDate()),toReceive=recOpen.reduce((a,r)=>a+Math.max(0,Number(r.amount)-Number(r.received_amount||0)),0),toPay=payOpen.reduce((a,r)=>a+Math.max(0,Number(r.amount)-Number(r.paid_amount||0)),0);$('financeStats').innerHTML=stat('A receber',brl(toReceive))+stat('A pagar',brl(toPay))+stat('Saldo projetado',brl(toReceive-toPay))+stat('Vencidos',brl(overdue.reduce((a,r)=>a+Number(r.amount)-Number(r.received_amount||0),0)));$('receivablesList').innerHTML=state.receivables.sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).map(r=>`<div class="record"><div class="record-main"><b>${esc(r.description||'Conta a receber')}</b><small>${esc(customerName(r.customer_id))}${r.order_id?' · '+esc(orderLabel(state.orders.find(o=>o.id===r.order_id)||{})):''}</small></div><div class="record-cell"><b>${brl(Number(r.amount)-Number(r.received_amount||0))}</b><small>de ${brl(r.amount)}</small></div><div class="record-cell"><span class="status ${statusClass(r.status)}">${esc(r.status)}</span><small class="${r.status!=='paid'&&r.due_date<localDate()?'danger-text':''}">${dateBR(r.due_date)}</small></div><div class="record-actions">${r.status!=='paid'?`<button class="small-btn good rec-paid" data-id="${r.id}">Receber</button>`:''}<button class="small-btn rec-edit" data-id="${r.id}">Editar</button></div></div>`).join('')||empty('Nenhuma conta a receber.');$('payablesList').innerHTML=state.payables.sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')).map(r=>`<div class="record"><div class="record-main"><b>${esc(r.description)}</b><small>${esc(supplierName(r.supplier_id))} · ${esc(r.cost_center||r.category||'sem centro de custo')}</small></div><div class="record-cell"><b>${brl(Number(r.amount)-Number(r.paid_amount||0))}</b><small>de ${brl(r.amount)}</small></div><div class="record-cell"><span class="status ${statusClass(r.status)}">${esc(r.status)}</span><small>${dateBR(r.due_date)}</small></div><div class="record-actions">${r.status!=='paid'?`<button class="small-btn good pay-paid" data-id="${r.id}">Pagar</button>`:''}<button class="small-btn pay-edit" data-id="${r.id}">Editar</button></div></div>`).join('')||empty('Nenhuma conta a pagar.');const entries=monthMovements();$('cashList').innerHTML=entries.map(m=>`<div class="record"><div class="record-main"><b>${esc(m.description)}</b><small>${esc(m.category||'sem categoria')} · ${dateTimeBR(m.created_at)}</small></div><div class="record-cell"><b class="${m.type==='entrada'?'good-text':'danger-text'}">${m.type==='entrada'?'+':'−'} ${brl(m.amount)}</b><small>${esc(m.nature||'operational')}</small></div><div></div><div></div></div>`).join('')||empty('Nenhum lançamento de caixa no mês.');$$('.rec-paid').forEach(b=>b.onclick=()=>markReceivablePaid(b.dataset.id));$$('.rec-edit').forEach(b=>b.onclick=()=>openReceivableModal(state.receivables.find(x=>x.id===b.dataset.id)));$$('.pay-paid').forEach(b=>b.onclick=()=>markPayablePaid(b.dataset.id));$$('.pay-edit').forEach(b=>b.onclick=()=>openPayableModal(state.payables.find(x=>x.id===b.dataset.id)))}
$$('.finance-tabs .tab').forEach(t=>t.onclick=()=>{$$('.finance-tabs .tab').forEach(x=>x.classList.toggle('active',x===t));$$('.finance-pane').forEach(x=>x.classList.remove('active'));$(`finance${t.dataset.fin[0].toUpperCase()+t.dataset.fin.slice(1)}`).classList.add('active')});$('newReceivableBtn').onclick=()=>openReceivableModal();$('newPayableBtn').onclick=()=>openPayableModal();

function renderInvestments(){const total=state.investments.reduce((a,i)=>a+Number(i.total_value||0),0),paid=state.investments.reduce((a,i)=>a+Math.min(Number(i.total_value||0),Number(i.paid_installments||0)*Number(i.installment_value||0)),0);$('investmentStats').innerHTML=stat('Capital investido',brl(total))+stat('Recuperado / pago',brl(paid))+stat('A recuperar',brl(Math.max(0,total-paid)))+stat('Equipamentos',state.investments.length);$('investmentsList').innerHTML=state.investments.map(i=>{const count=Math.max(1,Number(i.total_installments||1)),p=Math.min(count,Number(i.paid_installments||0)),progress=p/count*100;return`<article class="investment-card"><h4>${esc(i.name)}</h4><p>${dateBR(i.purchase_date)} · ${i.active===false?'Concluído':'Ativo'}</p><div class="investment-progress"><i style="width:${progress}%"></i></div><div class="investment-meta"><div><span>Parcelas</span><b>${p}/${count}</b></div><div><span>Parcela</span><b>${brl(i.installment_value)}</b></div><div><span>Total</span><b>${brl(i.total_value)}</b></div></div><div class="product-actions"><button class="small-btn investment-edit" data-id="${i.id}">Editar</button></div></article>`}).join('')||empty('Nenhum investimento cadastrado.');$$('.investment-edit').forEach(b=>b.onclick=()=>openInvestmentModal(state.investments.find(x=>x.id===b.dataset.id)))}
