$('ledgerMonth').onchange=renderLedger;$('newMovementBtn').onclick=()=>openMovementModal();

function renderAutomations(){const active=state.automations.filter(a=>a.active!==false);$('automationStats').innerHTML=stat('Regras',state.automations.length)+stat('Ativas',active.length)+stat('Tarefas automáticas',state.tasks.filter(t=>t.automation_key).length)+stat('Modo',db.cloudERP?'Nuvem + navegador':'Navegador');$('automationsList').innerHTML=state.automations.map(a=>`<article class="automation-card"><div class="automation-top"><h4>${esc(a.name)}</h4><button class="switch ${a.active!==false?'on':''}" data-auto="${a.id}"><i></i></button></div><p>Quando <b>${esc(a.trigger_event)}</b>, o sistema executa <b>${esc(a.action_type)}</b>${Number(a.delay_minutes)>0?` após ${Math.round(Number(a.delay_minutes)/60)}h`:''}.</p><div class="automation-flow"><span>${esc(a.trigger_event)}</span><span>→</span><span>${esc(a.action_type)}</span></div><div class="product-actions"><button class="small-btn auto-edit" data-id="${a.id}">Editar</button></div></article>`).join('')||empty('Nenhuma automação.');$$('[data-auto]').forEach(b=>b.onclick=async()=>{const a=state.automations.find(x=>x.id===b.dataset.auto);await db.update('automation_rules',a.id,{active:a.active===false});state.automations=await db.list('automation_rules');renderAutomations()});$$('.auto-edit').forEach(b=>b.onclick=()=>openAutomationModal(state.automations.find(x=>x.id===b.dataset.id)))}
