function fillSettings(){const s=state.settings||{};const map=[['setTradeName','trade_name'],['setLegalName','legal_name'],['setCnpj','cnpj'],['setIE','state_registration'],['setZip','zip_code'],['setAddress','address'],['setCity','city'],['setState','state'],['setPhone','phone'],['setWhatsapp','whatsapp'],['setEmail','email'],['setInstagram','instagram'],['setWebsite','website'],['setPix','pix_key'],['setTarget','monthly_revenue_target'],['setTax','tax_rate'],['setReceiptFooter','receipt_footer']];map.forEach(([id,k])=>$(id).value=s[k]??'');$('setMinMargin').value=minMargin()}
$('settingsForm').onsubmit=async e=>{e.preventDefault();const payload={user_id:state.user.id,trade_name:$('setTradeName').value.trim()||'Papel e Código',legal_name:$('setLegalName').value.trim()||null,cnpj:$('setCnpj').value.trim()||null,state_registration:$('setIE').value.trim()||null,zip_code:$('setZip').value.trim()||null,address:$('setAddress').value.trim()||null,city:$('setCity').value.trim()||null,state:$('setState').value.trim().toUpperCase()||null,phone:$('setPhone').value.trim()||null,whatsapp:$('setWhatsapp').value.trim()||null,email:$('setEmail').value.trim()||null,instagram:$('setInstagram').value.trim()||null,website:$('setWebsite').value.trim()||null,pix_key:$('setPix').value.trim()||null,monthly_revenue_target:Number($('setTarget').value||0),tax_rate:Number($('setTax').value||0),receipt_footer:$('setReceiptFooter').value.trim()||null,updated_at:new Date().toISOString()};const{error}=await supabase.from('company_settings').upsert(payload);if(error)return toast('Erro ao salvar configurações.',true);localStorage.setItem(`paco_min_margin_${state.user.id}`,String(Number($('setMinMargin').value||50)));state.settings=payload;renderDashboard();toast('Configurações salvas.')};

function showModal(title,eyebrow,html,submit,label='Salvar'){$('modalTitle').textContent=title;$('modalEyebrow').textContent=eyebrow;$('modalBody').innerHTML=html;$('saveModalBtn').textContent=label;modalSubmit=submit;$('entityDialog').showModal()}
function closeModal(){$('entityDialog').close();modalSubmit=null}
$('closeModalBtn').onclick=closeModal;$('cancelModalBtn').onclick=closeModal;$('entityForm').onsubmit=async e=>{e.preventDefault();if(!modalSubmit)return;const btn=$('saveModalBtn');btn.disabled=true;try{await modalSubmit(new FormData(e.target));closeModal()}catch(err){console.error(err);toast(err.message||'Não foi possível salvar.',true)}finally{btn.disabled=false}};

function openCustomerModal(c=null){showModal(c?'Editar cliente':'Novo cliente','CLIENTE',`<input type="hidden" name="id" value="${esc(c?.id||'')}"><div class="form-grid two"><label>Nome / contato<input name="name" required value="${esc(c?.name||'')}"></label><label>Razão social<input name="legal_name" value="${esc(c?.legal_name||'')}"></label></div><div class="form-grid three"><label>CPF/CNPJ<input name="document_number" value="${esc(c?.document_number||'')}"></label><label>WhatsApp<input name="whatsapp" value="${esc(c?.whatsapp||'')}"></label><label>E-mail<input type="email" name="email" value="${esc(c?.email||'')}"></label></div><div class="form-grid three"><label>Segmento<input name="segment" value="${esc(c?.segment||'')}"></label><label>Origem<input name="source" value="${esc(c?.source||'')}"></label><label>Responsável<select name="seller_name">${sellerOptions(c?.seller_name)}</select></label></div><label>Endereço<input name="address" value="${esc(c?.address||'')}"></label><div class="form-grid three"><label>Cidade<input name="city" value="${esc(c?.city||'')}"></label><label>UF<input name="state" maxlength="2" value="${esc(c?.state||'')}"></label><label>CEP<input name="zip_code" value="${esc(c?.zip_code||'')}"></label></div><label>Observações<textarea name="notes">${esc(c?.notes||'')}</textarea></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.active=true;p.document_type=p.document_number?(p.document_number.replace(/\D/g,'').length>11?'cnpj':'cpf'):null;const saved=id?await db.update('customers',id,p):await db.insert('customers',p);await db.audit('customer',saved.id,id?'update':'create',c,saved);state.customers=await db.list('customers');renderCustomers();toast(id?'Cliente atualizado.':'Cliente cadastrado.')})}

function quoteItemRow(item={}){return`<div class="quote-item-row"><label>Produto<select class="q-product" name="q_product"><option value="">Personalizado</option>${state.products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}" ${p.id===item.product_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Descrição<input class="q-desc" name="q_desc" required value="${esc(item.description||productName(item.product_id)||'')}"></label><label>Qtd.<input class="q-qty" name="q_qty" type="number" step="0.001" min="0.001" value="${item.quantity||1}"></label><label>Venda/un.<input class="q-price" name="q_price" type="number" step="0.01" min="0" value="${Number(item.unit_price||0)}"></label><label>Custo/un.<input class="q-cost" name="q_cost" type="number" step="0.01" min="0" value="${Number(item.unit_cost||0)}"></label><button type="button" class="remove-qitem">×</button></div>`}
function bindQuoteEditor(){const box=$('quoteItemsEditor'),add=()=>{box.insertAdjacentHTML('beforeend',quoteItemRow());bindQuoteEditor()};$('addQuoteItem').onclick=add;$$('.remove-qitem').forEach(b=>b.onclick=()=>{b.closest('.quote-item-row').remove();calcQuoteModal()});$$('.q-product').forEach(s=>s.onchange=()=>{const p=state.products.find(x=>x.id===s.value),row=s.closest('.quote-item-row');if(p){row.querySelector('.q-desc').value=p.name;row.querySelector('.q-price').value=p.sale_price||0;row.querySelector('.q-cost').value=p.direct_cost||0}calcQuoteModal()});$$('#quoteItemsEditor input').forEach(i=>i.oninput=calcQuoteModal);$('quoteDiscount').oninput=calcQuoteModal;calcQuoteModal()}
function calcQuoteModal(){const rows=$$('.quote-item-row'),subtotal=rows.reduce((a,r)=>a+Number(r.querySelector('.q-qty').value||0)*Number(r.querySelector('.q-price').value||0),0),cost=rows.reduce((a,r)=>a+Number(r.querySelector('.q-qty').value||0)*Number(r.querySelector('.q-cost').value||0),0),discount=Math.min(subtotal,Number($('quoteDiscount')?.value||0)),total=subtotal-discount,margin=total?(total-cost)/total*100:0,el=$('quoteMarginPreview');if(el){el.classList.toggle('bad',margin<minMargin()&&total>0);el.innerHTML=`Subtotal <b>${brl(subtotal)}</b> · Custo <b>${brl(cost)}</b> · Total <b>${brl(total)}</b> · Margem <b>${pct(margin)}</b>${margin<minMargin()&&total>0?' — abaixo do mínimo':''}`}return{subtotal,cost,discount,total,margin}}
function openQuoteModal(q=null,preProductId=null){const items=q?state.quoteItems.filter(i=>i.quote_id===q.id):preProductId?[{product_id:preProductId,description:productName(preProductId),quantity:1,unit_price:state.products.find(p=>p.id===preProductId)?.sale_price||0,unit_cost:state.products.find(p=>p.id===preProductId)?.direct_cost||0}]:[{}];showModal(q?'Editar orçamento':'Novo orçamento','ORÇAMENTO',`<input type="hidden" name="id" value="${esc(q?.id||'')}"><div class="form-grid three"><label>Cliente<select name="customer_id"><option value="">Selecione</option>${optionList(state.customers,'id','name',q?.customer_id)}</select></label><label>Responsável<select name="seller_name">${sellerOptions(q?.seller_name)}</select></label><label>Status<select name="status">${Object.entries(QUOTE_STATUS).map(([k,v])=>`<option value="${k}" ${q?.status===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="form-grid three"><label>Validade<input name="valid_until" type="date" value="${esc(q?.valid_until||'')}"></label><label>Prazo prometido<input name="promised_date" type="date" value="${esc(q?.promised_date||'')}"></label><label>Desconto<input id="quoteDiscount" name="discount" type="number" min="0" step="0.01" value="${Number(q?.discount||0)}"></label></div><div class="panel-head"><div><p class="eyebrow">ITENS</p><h3>Produtos e serviços</h3></div><button type="button" id="addQuoteItem" class="btn ghost small">+ Item</button></div><div id="quoteItemsEditor" class="quote-items-editor">${items.map(quoteItemRow).join('')}</div><div id="quoteMarginPreview" class="margin-preview"></div><label>Observações<textarea name="note">${esc(q?.note||'')}</textarea></label>`,async fd=>{const form=Object.fromEntries(fd.entries()),id=form.id;const calc=calcQuoteModal(),rows=$$('.quote-item-row').map(r=>({product_id:r.querySelector('.q-product').value||null,description:r.querySelector('.q-desc').value.trim(),quantity:Number(r.querySelector('.q-qty').value||1),unit_price:Number(r.querySelector('.q-price').value||0),unit_cost:Number(r.querySelector('.q-cost').value||0)})).filter(x=>x.description&&x.quantity>0);if(!rows.length)throw new Error('Inclua pelo menos um item.');const payload={customer_id:form.customer_id||null,seller_name:form.seller_name||null,status:form.status||'draft',valid_until:form.valid_until||null,promised_date:form.promised_date||null,discount:calc.discount,subtotal:calc.subtotal,total:calc.total,estimated_cost:calc.cost,estimated_margin:calc.margin/100,note:form.note||null,code:q?.code||code('ORC'),version:q?.version||1,sent_at:form.status==='sent'?(q?.sent_at||new Date().toISOString()):q?.sent_at||null};let saved;if(id){saved=await db.update('quotes',id,payload);for(const old of state.quoteItems.filter(x=>x.quote_id===id))await db.remove('quote_items',old.id)}else saved=await db.insert('quotes',payload);await db.insertMany('quote_items',rows.map(r=>({...r,quote_id:saved.id,total:r.quantity*r.unit_price,attributes:{}})));await db.audit('quote',saved.id,id?'update':'create',q,saved);await loadERP();renderQuotes();renderDashboard();toast(id?'Orçamento atualizado.':'Orçamento criado.')});setTimeout(bindQuoteEditor,0)}

function openOrderModal(o=null){showModal(o?'Editar pedido':'Pedido manual','PEDIDO',`<input type="hidden" name="id" value="${esc(o?.id||'')}"><div class="form-grid three"><label>Cliente<select name="customer_id"><option value="">Selecione</option>${optionList(state.customers,'id','name',o?.customer_id)}</select></label><label>Responsável<select name="seller_name">${sellerOptions(o?.seller_name)}</select></label><label>Status<select name="status">${ORDER_STAGES.map(k=>`<option value="${k}" ${o?.status===k?'selected':''}>${ORDER_STATUS[k]}</option>`).join('')}</select></label></div><div class="form-grid three"><label>Valor total<input name="total" type="number" min="0" step="0.01" value="${Number(o?.total||0)}"></label><label>Custo estimado<input name="estimated_cost" type="number" min="0" step="0.01" value="${Number(o?.estimated_cost||0)}"></label><label>Prazo<input name="promised_date" type="date" value="${esc(o?.promised_date||'')}"></label></div><div class="form-grid two"><label>Prioridade 0–100<input name="priority" type="number" min="0" max="100" value="${Number(o?.priority||0)}"></label><label>Código<input name="code" value="${esc(o?.code||code('PED'))}"></label></div><label>Observações<textarea name="note">${esc(o?.note||'')}</textarea></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.customer_id=p.customer_id||null;p.seller_name=p.seller_name||null;p.total=Number(p.total||0);p.estimated_cost=Number(p.estimated_cost||0);p.priority=Number(p.priority||0);p.promised_date=p.promised_date||null;const saved=id?await db.update('orders',id,p):await db.insert('orders',p);if(!id)await createDefaultProduction(saved);await db.audit('order',saved.id,id?'update':'create',o,saved);await loadERP();renderOrders();renderProduction();renderDashboard();toast(id?'Pedido atualizado.':'Pedido criado.')})}

function openTaskModal(t=null){showModal(t?'Editar tarefa':'Nova tarefa','TAREFA',`<input type="hidden" name="id" value="${esc(t?.id||'')}"><label>Título<input name="title" required value="${esc(t?.title||'')}"></label><div class="form-grid three"><label>Responsável<select name="assignee">${sellerOptions(t?.assignee)}</select></label><label>Prioridade<select name="priority">${Object.entries(TASK_PRIORITY).map(([k,v])=>`<option value="${k}" ${t?.priority===k?'selected':''}>${v}</option>`).join('')}</select></label><label>Prazo<input name="due_at" type="datetime-local" value="${t?.due_at?String(t.due_at).slice(0,16):''}"></label></div><div class="form-grid two"><label>Cliente<select name="customer_id"><option value="">Nenhum</option>${optionList(state.customers,'id','name',t?.customer_id)}</select></label><label>Pedido<select name="order_id"><option value="">Nenhum</option>${state.orders.map(o=>`<option value="${o.id}" ${t?.order_id===o.id?'selected':''}>${esc(orderLabel(o))} · ${esc(customerName(o.customer_id))}</option>`).join('')}</select></label></div><div class="form-grid two"><label>Tempo estimado (min)<input name="estimated_minutes" type="number" min="0" value="${Number(t?.estimated_minutes||0)}"></label><label>Status<select name="status"><option value="todo" ${t?.status==='todo'?'selected':''}>A fazer</option><option value="doing" ${t?.status==='doing'?'selected':''}>Fazendo</option><option value="done" ${t?.status==='done'?'selected':''}>Concluída</option></select></label></div><label>Descrição<textarea name="description">${esc(t?.description||'')}</textarea></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.customer_id=p.customer_id||null;p.order_id=p.order_id||null;p.assignee=p.assignee||null;p.due_at=p.due_at?new Date(p.due_at).toISOString():null;p.estimated_minutes=Number(p.estimated_minutes||0)||null;if(p.status==='done')p.completed_at=t?.completed_at||new Date().toISOString();const saved=id?await db.update('tasks',id,p):await db.insert('tasks',p);await db.audit('task',saved.id,id?'update':'create',t,saved);state.tasks=await db.list('tasks');renderTasks();renderDashboard();toast(id?'Tarefa atualizada.':'Tarefa criada.')})}

function fieldBuilderRows(fields=[]){return fields.map((f,i)=>`<div class="builder-row"><label>Campo<input class="pf-name" value="${esc(f.name||'')}"></label><label>Tipo<select class="pf-type"><option value="text" ${f.type==='text'?'selected':''}>Texto</option><option value="number" ${f.type==='number'?'selected':''}>Número</option><option value="select" ${f.type==='select'?'selected':''}>Seleção</option><option value="boolean" ${f.type==='boolean'?'selected':''}>Sim/Não</option><option value="date" ${f.type==='date'?'selected':''}>Data</option></select></label><label>Opções (se seleção)<input class="pf-options" value="${esc((f.options||[]).join(', '))}"></label><button type="button" class="remove-builder">×</button></div>`).join('')}
function recipeBuilderRows(rows=[]){return rows.map(r=>`<div class="builder-row"><label>Material / etapa<input class="pr-name" value="${esc(r.name||'')}"></label><label>Qtd./un.<input class="pr-qty" type="number" step="0.001" value="${Number(r.qty||1)}"></label><label>Custo/un.<input class="pr-cost" type="number" step="0.0001" value="${Number(r.cost||0)}"></label><button type="button" class="remove-builder">×</button></div>`).join('')}
function bindProductBuilders(){const fields=$('productFields'),recipe=$('productRecipe');$('addProductField').onclick=()=>{fields.insertAdjacentHTML('beforeend',fieldBuilderRows([{name:'',type:'text',options:[]}]));bindProductBuilders()};$('addRecipeRow').onclick=()=>{recipe.insertAdjacentHTML('beforeend',recipeBuilderRows([{name:'',qty:1,cost:0}]));bindProductBuilders()};$$('.remove-builder').forEach(b=>b.onclick=()=>b.closest('.builder-row').remove())}
function openProductModal(p=null){showModal(p?'Configurar produto':'Novo produto','CATÁLOGO',`<input type="hidden" name="id" value="${esc(p?.id||'')}"><div class="form-grid three"><label>Categoria<input name="category" required value="${esc(p?.category||'')}"></label><label>Produto<input name="name" required value="${esc(p?.name||'')}"></label><label>Subproduto / variação<input name="subproduct" value="${esc(p?.subproduct||'')}"></label></div><div class="form-grid four"><label>Unidade<input name="unit" value="${esc(p?.unit||'un')}"></label><label>Preço venda<input name="sale_price" type="number" min="0" step="0.01" value="${Number(p?.sale_price||0)}"></label><label>Custo direto<input name="direct_cost" type="number" min="0" step="0.01" value="${Number(p?.direct_cost||0)}"></label><label>Margem mín. %<input name="minimum_margin" type="number" min="0" max="99" step="0.1" value="${Number(p?.minimum_margin??minMargin())}"></label></div><label>Descrição<textarea name="description">${esc(p?.description||'')}</textarea></label><div class="field-builder"><div class="panel-head"><div><p class="eyebrow">CAMPOS PERSONALIZADOS</p><h3>O que o atendente deve preencher?</h3></div><button id="addProductField" type="button" class="btn ghost small">+ Campo</button></div><div id="productFields">${fieldBuilderRows(p?.custom_fields||[])}</div></div><div class="field-builder"><div class="panel-head"><div><p class="eyebrow">RECEITA / BOM</p><h3>Materiais e custos do produto</h3></div><button id="addRecipeRow" type="button" class="btn ghost small">+ Item</button></div><div id="productRecipe">${recipeBuilderRows(p?.recipe||[])}</div></div><label>Fluxo de produção (separe por vírgulas)<input name="workflow" value="${esc((p?.workflow||[]).join(', '))}" placeholder="Arte, Aprovação, Impressão, Corte, Conferência"></label>`,async fd=>{const x=Object.fromEntries(fd.entries()),id=x.id;delete x.id;const fields=$$('#productFields .builder-row').map(r=>({name:r.querySelector('.pf-name').value.trim(),type:r.querySelector('.pf-type').value,options:r.querySelector('.pf-options').value.split(',').map(s=>s.trim()).filter(Boolean)})).filter(f=>f.name),recipe=$$('#productRecipe .builder-row').map(r=>({name:r.querySelector('.pr-name').value.trim(),qty:Number(r.querySelector('.pr-qty').value||1),cost:Number(r.querySelector('.pr-cost').value||0)})).filter(r=>r.name);x.sale_price=Number(x.sale_price||0);x.direct_cost=Number(x.direct_cost||0);x.minimum_margin=Number(x.minimum_margin||minMargin());x.subproduct=x.subproduct||null;x.custom_fields=fields;x.recipe=recipe;x.workflow=x.workflow.split(',').map(s=>s.trim()).filter(Boolean);x.addons=p?.addons||[];x.pricing_rule=p?.pricing_rule||{type:'fixed'};x.active=true;const saved=id?await db.update('products',id,x):await db.insert('products',x);await db.audit('product',saved.id,id?'update':'create',p,saved);state.products=await db.list('products');renderCatalog();refreshSaleProductOptions();toast(id?'Produto atualizado.':'Produto criado.')});setTimeout(bindProductBuilders,0)}

function openLeadModal(l=null){showModal(l?'Editar atendimento':'Novo atendimento','CRM',`<input type="hidden" name="id" value="${esc(l?.id||'')}"><div class="form-grid two"><label>Cliente<input name="customer_name" required value="${esc(l?.customer_name||'')}"></label><label>WhatsApp<input name="customer_phone" value="${esc(l?.customer_phone||'')}"></label></div><div class="form-grid three"><label>Interesse<input name="service_interest" value="${esc(l?.service_interest||'')}"></label><label>Valor estimado<input name="estimated_value" type="number" min="0" step="0.01" value="${Number(l?.estimated_value||0)}"></label><label>Responsável<select name="seller_name">${sellerOptions(l?.seller_name)}</select></label></div><label>Observação<textarea name="note">${esc(l?.note||'')}</textarea></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.estimated_value=Number(p.estimated_value||0);p.seller_name=p.seller_name||null;p.customer_phone=p.customer_phone||null;let error;if(id)({error}=await supabase.from('leads').update({...p,updated_at:new Date().toISOString()}).eq('id',id));else({error}=await supabase.from('leads').insert({...p,user_id:state.user.id,stage:'novo'}));if(error)throw error;await loadOldCore();renderFunnel();renderDashboard();toast(id?'Atendimento atualizado.':'Atendimento criado.')})}

function openStockModal(s=null){showModal(s?'Editar insumo':'Novo insumo','ESTOQUE',`<input type="hidden" name="id" value="${esc(s?.id||'')}"><div class="form-grid two"><label>Insumo<input name="name" required value="${esc(s?.name||'')}"></label><label>Categoria<input name="category" value="${esc(s?.category||'')}"></label></div><div class="form-grid four"><label>Unidade<input name="unit" value="${esc(s?.unit||'un')}"></label><label>Estoque atual<input name="current_qty" type="number" step="0.001" value="${Number(s?.current_qty||0)}"></label><label>Estoque mínimo<input name="minimum_qty" type="number" step="0.001" value="${Number(s?.minimum_qty||0)}"></label><label>Custo médio<input name="average_cost" type="number" step="0.0001" value="${Number(s?.average_cost||0)}"></label></div><div class="form-grid two"><label>Fornecedor<select name="supplier_id"><option value="">Nenhum</option>${optionList(state.suppliers,'id','name',s?.supplier_id)}</select></label><label>Localização<input name="location" value="${esc(s?.location||'')}"></label></div>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.supplier_id=p.supplier_id||null;['current_qty','minimum_qty','average_cost'].forEach(k=>p[k]=Number(p[k]||0));p.reserved_qty=Number(s?.reserved_qty||0);p.active=true;id?await db.update('stock_items',id,p):await db.insert('stock_items',p);state.stock=await db.list('stock_items');renderStock();renderDashboard();toast(id?'Insumo atualizado.':'Insumo criado.')})}
function openStockMovementModal(s){showModal(`Movimentar ${s.name}`,'ESTOQUE',`<div class="form-grid three"><label>Tipo<select name="movement_type"><option value="in">Entrada</option><option value="out">Saída</option><option value="reserve">Reservar</option><option value="release">Liberar reserva</option><option value="adjustment">Ajuste +</option></select></label><label>Quantidade<input name="quantity" type="number" step="0.001" min="0.001" required></label><label>Custo unitário<input name="unit_cost" type="number" step="0.0001" value="${Number(s.average_cost||0)}"></label></div><label>Observação<input name="note"></label>`,async fd=>{const p=Object.fromEntries(fd.entries());p.quantity=Number(p.quantity);p.unit_cost=Number(p.unit_cost||0);p.stock_item_id=s.id;let current=Number(s.current_qty),reserved=Number(s.reserved_qty);if(p.movement_type==='in'||p.movement_type==='adjustment')current+=p.quantity;if(p.movement_type==='out')current=Math.max(0,current-p.quantity);if(p.movement_type==='reserve')reserved+=p.quantity;if(p.movement_type==='release')reserved=Math.max(0,reserved-p.quantity);await db.insert('stock_movements',p);await db.update('stock_items',s.id,{current_qty:current,reserved_qty:reserved,average_cost:p.movement_type==='in'&&p.unit_cost?p.unit_cost:s.average_cost});await loadERP();renderStock();renderDashboard();toast('Movimentação registrada.')})}

function openSupplierModal(s=null){showModal(s?'Editar fornecedor':'Novo fornecedor','FORNECEDOR',`<input type="hidden" name="id" value="${esc(s?.id||'')}"><div class="form-grid two"><label>Fornecedor<input name="name" required value="${esc(s?.name||'')}"></label><label>CPF/CNPJ<input name="document_number" value="${esc(s?.document_number||'')}"></label></div><div class="form-grid three"><label>WhatsApp<input name="whatsapp" value="${esc(s?.whatsapp||'')}"></label><label>E-mail<input type="email" name="email" value="${esc(s?.email||'')}"></label><label>Prazo médio (dias)<input name="lead_time_days" type="number" min="0" value="${Number(s?.lead_time_days||0)}"></label></div><label>Observações<textarea name="notes">${esc(s?.notes||'')}</textarea></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.lead_time_days=Number(p.lead_time_days||0);p.active=true;id?await db.update('suppliers',id,p):await db.insert('suppliers',p);state.suppliers=await db.list('suppliers');renderSuppliers();toast(id?'Fornecedor atualizado.':'Fornecedor criado.')})}

function openReceivableModal(r=null){showModal(r?'Editar conta a receber':'Nova conta a receber','FINANCEIRO',`<input type="hidden" name="id" value="${esc(r?.id||'')}"><label>Descrição<input name="description" required value="${esc(r?.description||'')}"></label><div class="form-grid three"><label>Cliente<select name="customer_id"><option value="">Nenhum</option>${optionList(state.customers,'id','name',r?.customer_id)}</select></label><label>Vencimento<input name="due_date" type="date" value="${esc(r?.due_date||localDate())}"></label><label>Valor<input name="amount" type="number" min="0" step="0.01" value="${Number(r?.amount||0)}"></label></div><div class="form-grid two"><label>Recebido<input name="received_amount" type="number" min="0" step="0.01" value="${Number(r?.received_amount||0)}"></label><label>Forma<select name="payment_method"><option value="">Não definida</option>${Object.entries(paymentNames).map(([k,v])=>`<option value="${k}" ${r?.payment_method===k?'selected':''}>${v}</option>`).join('')}</select></label></div>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.customer_id=p.customer_id||null;p.amount=Number(p.amount||0);p.received_amount=Number(p.received_amount||0);p.payment_method=p.payment_method||null;p.status=p.received_amount>=p.amount&&p.amount>0?'paid':p.received_amount>0?'partial':p.due_date<localDate()?'overdue':'pending';id?await db.update('receivables',id,p):await db.insert('receivables',p);state.receivables=await db.list('receivables');renderFinance();renderDashboard();toast('Conta a receber salva.')})}
function openPayableModal(r=null){showModal(r?'Editar conta a pagar':'Nova conta a pagar','FINANCEIRO',`<input type="hidden" name="id" value="${esc(r?.id||'')}"><label>Descrição<input name="description" required value="${esc(r?.description||'')}"></label><div class="form-grid three"><label>Fornecedor<select name="supplier_id"><option value="">Nenhum</option>${optionList(state.suppliers,'id','name',r?.supplier_id)}</select></label><label>Vencimento<input name="due_date" type="date" value="${esc(r?.due_date||localDate())}"></label><label>Valor<input name="amount" type="number" min="0" step="0.01" value="${Number(r?.amount||0)}"></label></div><div class="form-grid three"><label>Pago<input name="paid_amount" type="number" min="0" step="0.01" value="${Number(r?.paid_amount||0)}"></label><label>Categoria<input name="category" value="${esc(r?.category||'')}"></label><label>Centro de custo<input name="cost_center" value="${esc(r?.cost_center||'')}"></label></div>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.supplier_id=p.supplier_id||null;p.amount=Number(p.amount||0);p.paid_amount=Number(p.paid_amount||0);p.status=p.paid_amount>=p.amount&&p.amount>0?'paid':p.paid_amount>0?'partial':p.due_date<localDate()?'overdue':'pending';id?await db.update('payables',id,p):await db.insert('payables',p);state.payables=await db.list('payables');renderFinance();toast('Conta a pagar salva.')})}

function openInvestmentModal(i=null){showModal(i?'Editar investimento':'Novo investimento','INVESTIMENTO',`<input type="hidden" name="id" value="${esc(i?.id||'')}"><label>Nome / equipamento<input name="name" required value="${esc(i?.name||'')}"></label><div class="form-grid two"><label>Valor total<input name="total_value" type="number" min="0" step="0.01" value="${Number(i?.total_value||0)}"></label><label>Valor da parcela<input name="installment_value" type="number" min="0" step="0.01" value="${Number(i?.installment_value||0)}"></label></div><div class="form-grid three"><label>Total de parcelas<input name="total_installments" type="number" min="1" value="${Number(i?.total_installments||1)}"></label><label>Parcelas pagas<input name="paid_installments" type="number" min="0" value="${Number(i?.paid_installments||0)}"></label><label>Data da compra<input name="purchase_date" type="date" value="${esc(i?.purchase_date||'')}"></label></div><label>Observações<textarea name="note">${esc(i?.note||'')}</textarea></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;['total_value','installment_value','total_installments','paid_installments'].forEach(k=>p[k]=Number(p[k]||0));p.active=p.paid_installments<p.total_installments;p.user_id=state.user.id;p.updated_at=new Date().toISOString();let error;if(id)({error}=await supabase.from('investments').update(p).eq('id',id));else({error}=await supabase.from('investments').insert(p));if(error)throw error;await loadOldCore();renderInvestments();toast('Investimento salvo.')})}
function openMovementModal(){showModal('Novo lançamento','CAIXA',`<div class="form-grid three"><label>Tipo<select name="type"><option value="entrada">Entrada</option><option value="saida">Saída</option></select></label><label>Natureza<select name="nature"><option value="operational">Operacional</option><option value="investment">Investimento / máquina</option><option value="other">Outro</option></select></label><label>Categoria<input name="category"></label></div><label>Descrição<input name="description" required></label><label>Valor<input name="amount" type="number" min="0.01" step="0.01" required></label>`,async fd=>{const p=Object.fromEntries(fd.entries());p.amount=Number(p.amount);p.user_id=state.user.id;const{error}=await supabase.from('cash_movements').insert(p);if(error)throw error;await loadOldCore();renderLedger();renderFinance();renderDashboard();toast('Lançamento registrado.')})}
function openAutomationModal(a=null){showModal(a?'Editar automação':'Nova automação','AUTOMAÇÃO',`<input type="hidden" name="id" value="${esc(a?.id||'')}"><label>Nome<input name="name" required value="${esc(a?.name||'')}"></label><div class="form-grid three"><label>Evento<select name="trigger_event"><option value="quote_sent">Orçamento enviado</option><option value="quote_waiting">Orçamento aguardando</option><option value="quote_approved">Orçamento aprovado</option><option value="order_ready">Pedido pronto</option><option value="order_delivered">Pedido entregue</option><option value="receivable_due">Conta a vencer</option><option value="low_stock">Estoque baixo</option><option value="task_overdue">Tarefa atrasada</option></select></label><label>Ação<select name="action_type"><option value="create_task">Criar tarefa</option><option value="purchase_suggestion">Sugerir compra</option><option value="escalate_task">Elevar prioridade</option></select></label><label>Atraso (min)<input name="delay_minutes" type="number" min="0" value="${Number(a?.delay_minutes||0)}"></label></div><label>Título / instrução da ação<input name="action_title" value="${esc(a?.action_json?.title||'')}"></label>`,async fd=>{const p=Object.fromEntries(fd.entries()),id=p.id;delete p.id;p.delay_minutes=Number(p.delay_minutes||0);p.condition_json=a?.condition_json||{};p.action_json={title:p.action_title};delete p.action_title;p.active=a?.active!==false;id?await db.update('automation_rules',id,p):await db.insert('automation_rules',p);state.automations=await db.list('automation_rules');renderAutomations();toast('Automação salva.')})}

async function approveQuote(id){const q=state.quotes.find(x=>x.id===id);if(!q)return;if(!confirm(`Aprovar ${quoteLabel(q)} e gerar pedido, financeiro e produção?`))return;let orderId=await db.approveQuoteRPC(id);if(!orderId){const items=state.quoteItems.filter(i=>i.quote_id===id),o=await db.insert('orders',{quote_id:q.id,customer_id:q.customer_id,code:code('PED'),status:'approved',seller_name:q.seller_name,total:q.total,estimated_cost:q.estimated_cost,promised_date:q.promised_date,priority:50,note:q.note});orderId=o.id;await db.insertMany('order_items',items.map(i=>({order_id:o.id,quote_item_id:i.id,product_id:i.product_id||null,service_id:i.service_id||null,description:i.description,quantity:i.quantity,unit_price:i.unit_price,unit_cost:i.unit_cost,total:i.total,attributes:i.attributes||{}})));await db.insert('receivables',{customer_id:q.customer_id,order_id:o.id,description:`Pedido ${o.code}`,due_date:q.promised_date||localDate(),amount:q.total,received_amount:0,status:'pending'});await db.insert('tasks',{order_id:o.id,customer_id:q.customer_id,title:`Preparar pedido ${o.code}`,status:'todo',priority:'high',assignee:q.seller_name||null,due_at:q.promised_date?`${q.promised_date}T15:00:00-03:00`:null,automation_key:`quote_approved:${q.id}`});await db.update('quotes',q.id,{status:'approved',approved_at:new Date().toISOString()});await createDefaultProduction(o,items)}await refreshAll(true);nav('orders');toast('Orçamento aprovado e pedido criado.')}
async function createDefaultProduction(order,quoteItems=[]){const items=quoteItems.length?quoteItems:state.orderItems.filter(i=>i.order_id===order.id),workflows=[];items.forEach(i=>{const p=state.products.find(x=>x.id===i.product_id);(p?.workflow||[]).forEach(x=>{if(!workflows.includes(x))workflows.push(x)})});const wf=workflows.length?workflows:['Arte','Aprovação','Impressão','Acabamento','Conferência','Entrega'];await db.insertMany('production_steps',wf.map((title,i)=>({order_id:order.id,title,stage:ORDER_STAGES[Math.min(i,ORDER_STAGES.length-2)],position:i,status:'todo',assignee:order.seller_name||null})));return wf}
async function advanceOrder(id){const o=state.orders.find(x=>x.id===id);if(!o)return;const i=ORDER_STAGES.indexOf(o.status),next=ORDER_STAGES[Math.min(ORDER_STAGES.length-1,i+1)];await moveOrder(id,next)}
async function moveOrder(id,status){const o=state.orders.find(x=>x.id===id);if(!o||o.status===status)return;await db.update('orders',id,{status});if(status==='ready')await ensureAutoTask(`order_ready:${id}`,{order_id:id,customer_id:o.customer_id,title:`Avisar ${customerName(o.customer_id)}: pedido ${orderLabel(o)} pronto`,priority:'normal'});if(status==='delivered')await ensureAutoTask(`order_delivered:${id}`,{order_id:id,customer_id:o.customer_id,title:`Pós-venda do pedido ${orderLabel(o)}`,priority:'normal',due_at:new Date(Date.now()+7*86400000).toISOString()});await loadERP();renderOrders();renderProduction();renderDashboard();toast(`Pedido movido para ${ORDER_STATUS[status]}.`)}
async function completeTask(id){await db.update('tasks',id,{status:'done',completed_at:new Date().toISOString()});state.tasks=await db.list('tasks');renderTasks();renderDashboard()}
async function moveLead(id,stage){const{error}=await supabase.from('leads').update({stage,updated_at:new Date().toISOString()}).eq('id',id);if(error)return toast('Erro ao mover atendimento.',true);await loadOldCore();renderFunnel();renderDashboard()}
async function createPurchaseSuggestion(stockId,quantity){const s=state.stock.find(x=>x.id===stockId),existing=state.purchaseRequests.find(x=>x.stock_item_id===stockId&&!['received','cancelled'].includes(x.status));if(existing)return toast('Já existe uma solicitação aberta para este insumo.');await db.insert('purchase_requests',{stock_item_id:stockId,supplier_id:s.supplier_id||null,quantity,estimated_cost:quantity*Number(s.average_cost||0),status:'requested',needed_by:localDate(),note:'Gerada a partir do estoque mínimo'});state.purchaseRequests=await db.list('purchase_requests');toast('Solicitação de compra criada.')}
async function markReceivablePaid(id){const r=state.receivables.find(x=>x.id===id);if(!r)return;const remaining=Math.max(0,Number(r.amount)-Number(r.received_amount||0));await db.update('receivables',id,{received_amount:r.amount,status:'paid',paid_at:new Date().toISOString()});if(remaining>0)await addCash('entrada',remaining,'Recebimento',r.description||'Conta recebida','operational');await refreshAll(true);renderFinance();renderDashboard();toast('Recebimento baixado.')}
async function markPayablePaid(id){const r=state.payables.find(x=>x.id===id);if(!r)return;const remaining=Math.max(0,Number(r.amount)-Number(r.paid_amount||0));await db.update('payables',id,{paid_amount:r.amount,status:'paid',paid_at:new Date().toISOString()});if(remaining>0)await addCash('saida',remaining,r.category||'Conta a pagar',r.description,'operational');await refreshAll(true);renderFinance();renderDashboard();toast('Pagamento baixado.')}
async function addCash(type,amount,category,description,nature='operational'){const{error}=await supabase.from('cash_movements').insert({user_id:state.user.id,type,amount,category,description,nature});if(error)console.warn('Caixa não atualizado',error)}

async function runAutonomy(){
  const activeRules=state.automations.filter(a=>a.active!==false),has=e=>activeRules.some(a=>a.trigger_event===e);
  if(has('task_overdue'))for(const t of state.tasks.filter(t=>!['done','cancelled'].includes(t.status)&&t.due_at&&new Date(t.due_at)<new Date()&&t.priority!=='critical'))await db.update('tasks',t.id,{priority:'critical'});
  if(has('low_stock'))for(const s of state.stock.filter(s=>Number(s.current_qty)-Number(s.reserved_qty)<=Number(s.minimum_qty))){const key=`low_stock:${s.id}:${localDate()}`;await ensureAutoTask(key,{title:`Repor estoque: ${s.name}`,description:`Disponível: ${Number(s.current_qty)-Number(s.reserved_qty)} ${s.unit}. Mínimo: ${s.minimum_qty}.`,priority:'high'})}
  if(has('quote_sent'))for(const q of state.quotes.filter(q=>q.status==='sent'&&Date.now()-new Date(q.sent_at||q.updated_at||q.created_at).getTime()>=86400000))await ensureAutoTask(`quote_followup:${q.id}`,{customer_id:q.customer_id,title:`Follow-up ${quoteLabel(q)} · ${customerName(q.customer_id)}`,priority:'normal'});
  if(has('quote_waiting'))for(const q of state.quotes.filter(q=>['sent','waiting'].includes(q.status)&&ageDays(q.updated_at||q.created_at)>=3))await ensureAutoTask(`quote_3d:${q.id}`,{customer_id:q.customer_id,title:`Retomar orçamento ${quoteLabel(q)} sem resposta`,priority:'high'});
  if(has('receivable_due')){const tomorrow=new Date(Date.now()+86400000).toISOString().slice(0,10);for(const r of state.receivables.filter(r=>r.status!=='paid'&&r.due_date===tomorrow))await ensureAutoTask(`due:${r.id}`,{customer_id:r.customer_id,order_id:r.order_id,title:`Cobrança vence amanhã: ${r.description||brl(r.amount)}`,priority:'high'})}
  const changed=state.tasks.some(t=>t.priority==='critical');if(changed)state.tasks=await db.list('tasks');
}
async function ensureAutoTask(key,payload){if(state.tasks.some(t=>t.automation_key===key))return;const t=await db.insert('tasks',{...payload,status:'todo',automation_key:key});state.tasks.push(t)}

function refreshSaleProductOptions(){$$('.sale-product').forEach(sel=>{const v=sel.value;sel.innerHTML='<option value="">Personalizado</option>'+state.products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');sel.value=v})}
function addSaleItem(pref={}){const div=document.createElement('div');div.className='sale-item';div.innerHTML=`<label>Produto<select class="sale-product"><option value="">Personalizado</option>${state.products.filter(p=>p.active!==false).map(p=>`<option value="${p.id}" ${p.id===pref.product_id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Descrição<input class="sale-desc" value="${esc(pref.description||'')}"></label><label>Qtd.<input class="sale-qty" type="number" min="0.001" step="0.001" value="${pref.quantity||1}"></label><label>Venda/un.<input class="sale-price" type="number" min="0" step="0.01" value="${Number(pref.unit_price||0)}"></label><label>Custo/un.<input class="sale-cost" type="number" min="0" step="0.01" value="${Number(pref.unit_cost||0)}"></label><button type="button" class="remove">×</button>`;$('saleItems').appendChild(div);div.querySelector('.sale-product').onchange=e=>{const p=state.products.find(x=>x.id===e.target.value);if(p){div.querySelector('.sale-desc').value=p.name;div.querySelector('.sale-price').value=p.sale_price||0;div.querySelector('.sale-cost').value=p.direct_cost||0}calcSale()};div.querySelectorAll('input').forEach(i=>i.oninput=calcSale);div.querySelector('.remove').onclick=()=>{div.remove();calcSale()};calcSale()}
function calcSale(){let sub=0;$$('.sale-item').forEach(r=>sub+=Number(r.querySelector('.sale-qty').value||0)*Number(r.querySelector('.sale-price').value||0));const discount=Math.min(sub,Number($('saleDiscount').value||0)),total=Math.max(0,sub-discount);$('saleSubtotal').textContent=brl(sub);$('saleTotal').textContent=brl(total);return{sub,discount,total}}
$('addSaleItemBtn').onclick=()=>addSaleItem();$('saleDiscount').oninput=calcSale;addSaleItem();
$('finishSaleBtn').onclick=async()=>{const seller=$('saleSeller').value;if(!seller)return toast('Selecione o responsável.',true);const rows=$$('.sale-item').map(r=>({product_id:r.querySelector('.sale-product').value||null,description:r.querySelector('.sale-desc').value.trim(),quantity:Number(r.querySelector('.sale-qty').value||0),unit_price:Number(r.querySelector('.sale-price').value||0),unit_cost:Number(r.querySelector('.sale-cost').value||0)})).filter(x=>x.description&&x.quantity>0);if(!rows.length)return toast('Adicione pelo menos um item.',true);const calc=calcSale();if(calc.total<=0)return toast('Informe o valor da venda.',true);const payload={user_id:state.user.id,seller_name:seller,customer_name:$('saleCustomer').value.trim()||null,customer_phone:$('salePhone').value.trim()||null,note:$('saleNote').value.trim()||null,subtotal:calc.sub,discount:calc.discount,total:calc.total,payment_method:$('salePayment').value};const{data:sale,error}=await supabase.from('sales').insert(payload).select().single();if(error)return toast('Erro ao registrar venda.',true);const items=rows.map(r=>({sale_id:sale.id,service_id:null,description:r.description,quantity:r.quantity,unit_price:r.unit_price,unit_cost:r.unit_cost,total:r.quantity*r.unit_price}));const{error:ei}=await supabase.from('sale_items').insert(items);if(ei)return toast('Venda salva, mas os itens falharam.',true);state.lastSale={...sale,sale_items:items};await autoCustomerFromSale(payload);await loadOldCore();renderDashboard();$('receiptTitle').textContent=payload.customer_name?`Venda de ${payload.customer_name} registrada.`:'Venda registrada.';$('receiptTotal').textContent=brl(calc.total);$('receiptDialog').showModal();resetSale()};
function resetSale(){$('saleCustomer').value='';$('salePhone').value='';$('saleNote').value='';$('saleDiscount').value=0;$('saleItems').innerHTML='';addSaleItem();calcSale()}
async function autoCustomerFromSale(p){if(!p.customer_name)return;const found=state.customers.find(c=>c.name.toLowerCase()===p.customer_name.toLowerCase()||p.customer_phone&&[c.phone,c.whatsapp].includes(p.customer_phone));if(!found){await db.insert('customers',{name:p.customer_name,whatsapp:p.customer_phone||null,seller_name:p.seller_name,source:'Venda rápida',active:true});state.customers=await db.list('customers')}}

function openWhatsapp(phone,text=''){let d=String(phone||'').replace(/\D/g,'');if(!d)return toast('WhatsApp não informado.',true);if(!d.startsWith('55'))d='55'+d;window.open(`https://wa.me/${d}${text?'?text='+encodeURIComponent(text):''}`,'_blank','noopener')}
async function downloadQuote(q){const items=state.quoteItems.filter(i=>i.quote_id===q.id),doc=new jsPDF({unit:'mm',format:'a4'}),s=state.settings||{};doc.setFillColor(8,23,43);doc.rect(0,0,210,34,'F');doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(16);doc.text(s.trade_name||'Papel e Código',16,15);doc.setTextColor(223,240,31);doc.setFontSize(9);doc.text('ORÇAMENTO',16,23);doc.setTextColor(25,35,50);doc.setFontSize(12);doc.text(quoteLabel(q),16,47);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.text(`Cliente: ${customerName(q.customer_id)}`,16,56);doc.text(`Validade: ${dateBR(q.valid_until)}`,140,56);let y=70;doc.setFillColor(244,247,251);doc.rect(16,y-5,178,8,'F');doc.setFont('helvetica','bold');doc.text('Descrição',18,y);doc.text('Qtd.',128,y);doc.text('Unit.',150,y);doc.text('Total',192,y,{align:'right'});y+=9;doc.setFont('helvetica','normal');items.forEach(i=>{doc.text(String(i.description).slice(0,62),18,y);doc.text(String(i.quantity),130,y);doc.text(brl(i.unit_price),150,y);doc.text(brl(i.total),192,y,{align:'right'});y+=7});y+=6;doc.setFont('helvetica','bold');doc.setFontSize(12);doc.text(`TOTAL ${brl(q.total)}`,194,y,{align:'right'});y+=10;doc.setFont('helvetica','normal');doc.setFontSize(9);if(q.note)doc.text(`Observações: ${String(q.note).slice(0,120)}`,16,y);doc.save(`${quoteLabel(q)}.pdf`)}
async function saleReceiptDoc(sale){const doc=new jsPDF({unit:'mm',format:'a4'}),set=state.settings||{};doc.setFillColor(8,23,43);doc.rect(0,0,210,34,'F');doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(16);doc.text(set.trade_name||'Papel e Código',16,15);doc.setTextColor(223,240,31);doc.setFontSize(9);doc.text('RECIBO DE VENDA',16,23);doc.setTextColor(25,35,50);let y=48;doc.setFontSize(10);doc.text(`Cliente: ${sale.customer_name||'Venda balcão'}`,16,y);y+=12;(sale.sale_items||[]).forEach(i=>{doc.setFont('helvetica','normal');doc.text(`${i.quantity} × ${String(i.description).slice(0,60)}`,16,y);doc.text(brl(i.total),194,y,{align:'right'});y+=7});y+=6;doc.setFont('helvetica','bold');doc.setFontSize(13);doc.text(`TOTAL ${brl(sale.total)}`,194,y,{align:'right'});return doc}
$('closeReceiptBtn').onclick=()=>$('receiptDialog').close();$('receiptPdfBtn').onclick=async()=>{if(!state.lastSale)return;const doc=await saleReceiptDoc(state.lastSale);doc.save(`REC-${String(state.lastSale.id).slice(0,8).toUpperCase()}.pdf`)};$('receiptWhatsappBtn').onclick=()=>{if(!state.lastSale)return;openWhatsapp(state.lastSale.customer_phone,`Olá, ${state.lastSale.customer_name||'cliente'}! Sua compra na Papel e Código no valor de ${brl(state.lastSale.total)} foi registrada.`)};

function openGlobalSearch(){if(!$('searchDialog').open)$('searchDialog').showModal();$('globalSearch').value='';renderGlobalSearch('');setTimeout(()=>$('globalSearch').focus(),30)}
$('globalSearchBtn').onclick=openGlobalSearch;$('closeSearchBtn').onclick=()=>$('searchDialog').close();$('globalSearch').oninput=e=>renderGlobalSearch(e.target.value);document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openGlobalSearch()}if(e.key==='Escape'&&$('searchDialog').open)$('searchDialog').close()});
function renderGlobalSearch(query){const q=query.toLowerCase().trim(),rows=[];state.customers.forEach(x=>{if(!q||[x.name,x.whatsapp,x.email].some(v=>String(v||'').toLowerCase().includes(q)))rows.push(['Cliente',x.name,x.whatsapp||x.email||'',()=>{ $('searchDialog').close();nav('customers')}])});state.quotes.forEach(x=>{if(!q||quoteLabel(x).toLowerCase().includes(q)||customerName(x.customer_id).toLowerCase().includes(q))rows.push(['Orçamento',quoteLabel(x),`${customerName(x.customer_id)} · ${brl(x.total)}`,()=>{ $('searchDialog').close();nav('quotes')}])});state.orders.forEach(x=>{if(!q||orderLabel(x).toLowerCase().includes(q)||customerName(x.customer_id).toLowerCase().includes(q))rows.push(['Pedido',orderLabel(x),`${customerName(x.customer_id)} · ${ORDER_STATUS[x.status]}`,()=>{ $('searchDialog').close();nav('orders')}])});state.products.forEach(x=>{if(!q||[x.name,x.category].some(v=>String(v).toLowerCase().includes(q)))rows.push(['Produto',x.name,x.category,()=>{ $('searchDialog').close();nav('catalog')}])});$('searchResults').innerHTML=rows.slice(0,30).map((x,i)=>`<div class="search-result" data-i="${i}"><div><b>${esc(x[1])}</b><small>${esc(x[2])}</small></div><span>${esc(x[0])}</span></div>`).join('')||empty('Nada encontrado.');$$('#searchResults [data-i]').forEach(e=>e.onclick=rows[Number(e.dataset.i)][3])}

restore();
